refentry.refsect1:
  &reftitle.examples;

   Exemplo de Yac::set


<?php
$yac = new Yac();

$yac->set("foo", "bar");                    // armazena um único valor
$yac->set("foo", "baz");                    // sobrescreve a entrada existente
?>




   Definindo uma entrada com TTL


<?php
$yac = new Yac();

// TTL em segundos: a entrada expira após 5 segundos
$yac->set("short-lived", "value", 5);
sleep(6);
var_dump($yac->get("short-lived"));        // bool(false): expirada
?>




   Definindo várias entradas de uma vez


<?php
$yac = new Yac();

// armazena vários pares chave => valor em uma chamada
$yac->set(array("a" => 1, "b" => 2));
?>
